package com.servicerca.controller;import com.servicerca.dto.report.*;import com.servicerca.security.SecurityUser;import com.servicerca.service.ReportService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reports")public class ReportController{private final ReportService service;public ReportController(ReportService s){service=s;}@PostMapping public ResponseEntity<ReportResponse>create(@AuthenticationPrincipal SecurityUser u,@Valid@RequestBody CreateReportRequest r){return ResponseEntity.status(201).body(service.create(u.user(),r));}}
